using Microsoft.ML.Data;

namespace TicketClassifier.Models;

public class TicketInput
{
    [LoadColumn(0)]
    public string Subject { get; set; } = string.Empty;

    [LoadColumn(1)]
    public string Description { get; set; } = string.Empty;

    [LoadColumn(2)]
    public float Priority { get; set; }

    [LoadColumn(3)]
    public string Category { get; set; } = string.Empty;
}

public class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string Category { get; set; } = string.Empty;

    public float[] Score { get; set; } = [];
}

public class TicketRequest
{
    public required string Subject { get; set; }
    public required string Description { get; set; }
    public int Priority { get; set; }
}

public class PredictionResponse
{
    public required string PredictedCategory { get; set; }
    public required Dictionary<string, float> Confidence { get; set; }
}

public class TrainingMetrics
{
    public double MacroAccuracy { get; set; }
    public double MicroAccuracy { get; set; }
    public double LogLoss { get; set; }
    public required List<CategoryMetric> PerCategory { get; set; }
}

public class CategoryMetric
{
    public required string Category { get; set; }
    public double Precision { get; set; }
    public double Recall { get; set; }
    public double F1Score { get; set; }
}

using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class ModelTrainingService
{
    private readonly MLContext _mlContext = new(seed: 42);
    private readonly string _dataPath;
    private readonly string _modelPath;
    private readonly ILogger<ModelTrainingService> _logger;

    private TrainingMetrics? _lastMetrics;

    public ModelTrainingService(ILogger<ModelTrainingService> logger, IWebHostEnvironment env)
    {
        _logger = logger;
        _dataPath = Path.Combine(env.ContentRootPath, "Data", "tickets.csv");
        _modelPath = Path.Combine(env.ContentRootPath, "Data", "model.zip");
    }

    public TrainingMetrics? LastMetrics => _lastMetrics;

    public string ModelPath => _modelPath;

    public TrainingMetrics TrainAndEvaluate()
    {
        _logger.LogInformation("Loading training data from {Path}", _dataPath);

        var data = _mlContext.Data.LoadFromTextFile<TicketInput>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

        // Featurize text columns, combine with numeric Priority, then classify
        var pipeline = _mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketInput.Category))
            .Append(_mlContext.Transforms.Text
                .FeaturizeText("SubjectFeatures", nameof(TicketInput.Subject)))
            .Append(_mlContext.Transforms.Text
                .FeaturizeText("DescriptionFeatures", nameof(TicketInput.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeatures", "DescriptionFeatures", nameof(TicketInput.Priority)))
            .Append(_mlContext.MulticlassClassification.Trainers
                .SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion
                .MapKeyToValue("PredictedLabel"));

        _logger.LogInformation("Training model...");
        var model = pipeline.Fit(split.TrainSet);

        _logger.LogInformation("Evaluating model...");
        var predictions = model.Transform(split.TestSet);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions, "Label");

        _logger.LogInformation(
            "Model evaluation — MacroAccuracy: {Macro:F4}, MicroAccuracy: {Micro:F4}, LogLoss: {LogLoss:F4}",
            metrics.MacroAccuracy, metrics.MicroAccuracy, metrics.LogLoss);

        // Build per-category metrics from the confusion matrix
        var cm = metrics.ConfusionMatrix;
        var perCategory = new List<CategoryMetric>();
        for (var i = 0; i < cm.PerClassPrecision.Count; i++)
        {
            var name = cm.GetFormattedConfusionTable().Contains(cm.PerClassPrecision[i].ToString())
                ? $"Class{i}"
                : $"Class{i}";

            perCategory.Add(new CategoryMetric
            {
                Category = i < cm.PerClassPrecision.Count ? $"Class{i}" : $"Unknown",
                Precision = cm.PerClassPrecision[i],
                Recall = cm.PerClassRecall[i],
                F1Score = 2 * cm.PerClassPrecision[i] * cm.PerClassRecall[i]
                    / (cm.PerClassPrecision[i] + cm.PerClassRecall[i] + 1e-10),
            });
        }

        _lastMetrics = new TrainingMetrics
        {
            MacroAccuracy = metrics.MacroAccuracy,
            MicroAccuracy = metrics.MicroAccuracy,
            LogLoss = metrics.LogLoss,
            PerCategory = perCategory,
        };

        _mlContext.Model.Save(model, split.TrainSet.Schema, _modelPath);
        _logger.LogInformation("Model saved to {Path}", _modelPath);

        return _lastMetrics;
    }
}

using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class TicketController : ControllerBase
{
    private readonly PredictionEnginePool<TicketInput, TicketPrediction> _predictionPool;
    private readonly ModelTrainingService _trainingService;

    private static readonly string[] Categories = ["Billing", "General", "Technical"];

    public TicketController(
        PredictionEnginePool<TicketInput, TicketPrediction> predictionPool,
        ModelTrainingService trainingService)
    {
        _predictionPool = predictionPool;
        _trainingService = trainingService;
    }

    /// <summary>Predict the category for a support ticket.</summary>
    [HttpPost("classify")]
    public ActionResult<PredictionResponse> Classify([FromBody] TicketRequest request)
    {
        var input = new TicketInput
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority,
        };

        var prediction = _predictionPool.Predict(input);

        var confidence = new Dictionary<string, float>();
        for (var i = 0; i < Math.Min(Categories.Length, prediction.Score.Length); i++)
        {
            confidence[Categories[i]] = prediction.Score[i];
        }

        return Ok(new PredictionResponse
        {
            PredictedCategory = prediction.Category,
            Confidence = confidence,
        });
    }

    /// <summary>Retrain the model and return evaluation metrics.</summary>
    [HttpPost("train")]
    public ActionResult<TrainingMetrics> Train()
    {
        var metrics = _trainingService.TrainAndEvaluate();
        return Ok(metrics);
    }

    /// <summary>Get the most recent evaluation metrics.</summary>
    [HttpGet("metrics")]
    public ActionResult<TrainingMetrics> GetMetrics()
    {
        var metrics = _trainingService.LastMetrics;
        if (metrics is null)
            return NotFound("No training metrics available. Call POST /api/ticket/train first.");

        return Ok(metrics);
    }
}

