using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class ModelTrainingService
{
    private readonly MLContext _mlContext = new(seed: 42);
    private readonly string _dataPath;
    private readonly string _modelPath;
    private readonly ILogger<ModelTrainingService> _logger;

    private TrainingMetrics? _lastMetrics;
    private string[] _labelNames = [];

    public ModelTrainingService(ILogger<ModelTrainingService> logger, IWebHostEnvironment env)
    {
        _logger = logger;
        _dataPath = Path.Combine(env.ContentRootPath, "Data", "tickets.csv");
        _modelPath = Path.Combine(env.ContentRootPath, "Data", "model.zip");
    }

    public TrainingMetrics? LastMetrics => _lastMetrics;

    public string ModelPath => _modelPath;

    /// <summary>The ordered label names matching the Score array indices.</summary>
    public string[] LabelNames => _labelNames;

    public TrainingMetrics TrainAndEvaluate()
    {
        _logger.LogInformation("Loading training data from {Path}", _dataPath);

        var data = _mlContext.Data.LoadFromTextFile<TicketInput>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

        // Featurize text columns, combine with numeric Priority, then classify
        var pipeline = _mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketInput.Category))
            .Append(_mlContext.Transforms.Text
                .FeaturizeText("SubjectFeatures", nameof(TicketInput.Subject)))
            .Append(_mlContext.Transforms.Text
                .FeaturizeText("DescriptionFeatures", nameof(TicketInput.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeatures", "DescriptionFeatures", nameof(TicketInput.Priority)))
            .Append(_mlContext.MulticlassClassification.Trainers
                .SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion
                .MapKeyToValue("PredictedLabel"));

        _logger.LogInformation("Training model...");
        var model = pipeline.Fit(split.TrainSet);

        // Extract the label key-to-value mapping so Score indices are correct
        var transformedData = model.Transform(split.TrainSet);
        var labelColumn = transformedData.Schema["Label"];
        var keyValues = new VBuffer<ReadOnlyMemory<char>>();
        labelColumn.GetKeyValues(ref keyValues);
        _labelNames = keyValues.DenseValues().Select(v => v.ToString()).ToArray();

        _logger.LogInformation("Evaluating model...");
        var predictions = model.Transform(split.TestSet);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions, "Label");

        _logger.LogInformation(
            "Model evaluation — MacroAccuracy: {Macro:F4}, MicroAccuracy: {Micro:F4}, LogLoss: {LogLoss:F4}",
            metrics.MacroAccuracy, metrics.MicroAccuracy, metrics.LogLoss);

        var cm = metrics.ConfusionMatrix;
        var perCategory = new List<CategoryMetric>();
        for (var i = 0; i < cm.PerClassPrecision.Count; i++)
        {
            var name = i < _labelNames.Length ? _labelNames[i] : $"Class{i}";
            var precision = cm.PerClassPrecision[i];
            var recall = cm.PerClassRecall[i];

            perCategory.Add(new CategoryMetric
            {
                Category = name,
                Precision = precision,
                Recall = recall,
                F1Score = precision + recall > 0
                    ? 2 * precision * recall / (precision + recall)
                    : 0,
            });
        }

        _lastMetrics = new TrainingMetrics
        {
            MacroAccuracy = metrics.MacroAccuracy,
            MicroAccuracy = metrics.MicroAccuracy,
            LogLoss = metrics.LogLoss,
            PerCategory = perCategory,
        };

        _mlContext.Model.Save(model, split.TrainSet.Schema, _modelPath);
        _logger.LogInformation("Model saved to {Path}", _modelPath);

        return _lastMetrics;
    }
}

